import * as fs from "fs";

// 標準入力（左の「入力例」の内容）を 1 つの文字列として受け取り、
// 改行で区切って 1 行ずつの配列にする
const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 入力例 1 のとき:
//   input[0] は "4"
//   input[1] は "the quick brown fox"

// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const words = second.split(" ");

let best = words[0];
for (const w of words) {
  // 「より長い」ときだけ更新すれば、同じ長さでは最初のものが残る
  if (w.length > best.length) best = w;
}
console.log(best);
